import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const content = new Group();

  root.add(content);
  root.userData.handlers = {};

  const ownedGeometries = [];
  const ownedMaterials = [];
  const primitiveResults = [];
  let loadedTexture = null;
  let disposed = false;

  const makeMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makePlane = (width, height, material, z = 0) => {
    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.push(geometry);

    const mesh = new Mesh(geometry, material);
    mesh.position.z = z;
    return mesh;
  };

  const panelMaterial = makeMaterial();
  panelMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y)
  );

  const panel = makePlane(2.65, 0.76, panelMaterial, 0);
  content.add(panel);

  const textureMaterial = makeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0.2,
    depthWrite: false
  });

  const textureLayer = makePlane(2.53, 0.64, textureMaterial, 0.012);
  content.add(textureLayer);

  const accentMaterial = makeMaterial({
    color: 0xff2a38
  });

  const accentBar = makePlane(0.065, 0.76, accentMaterial, 0.028);
  accentBar.position.x = -1.2925;
  content.add(accentBar);

  const innerAccentMaterial = makeMaterial({
    color: 0xff2a38,
    transparent: true,
    opacity: 0.32,
    depthWrite: false
  });

  const innerAccent = makePlane(0.025, 0.56, innerAccentMaterial, 0.034);
  innerAccent.position.x = 1.218;
  content.add(innerAccent);

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textGroup = new Group();
  textGroup.position.set(0.1, 0, 0.045);
  content.add(textGroup);

  const lineHeight = 0.16;
  const startY = ((items.length - 1) * lineHeight) * 0.5;

  items.forEach((item, index) => {
    if (typeof item?.text !== 'string') return;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 42,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 420,
      letterSpacingPx: item.role === 'caption' ? 2 : 0
    });

    textObject.position.y = startY - index * lineHeight;
    textGroup.add(textObject);
  });

  const textureUrl = config.imageUrl;
  if (textureUrl) {
    ctx.textureLoader.loadTexture(textureUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      loadedTexture = texture;
      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      textureMaterial.map = texture;
      textureMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entranceTimeline = gsap.timeline();
  entranceTimeline.fromTo(
    content.position,
    { y: -0.16 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  entranceTimeline.fromTo(
    content.scale,
    { x: 0.97, y: 0.97, z: 0.97 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '<'
  );

  for (const primitive of config.cinematicPrimitives ?? []) {
    const primitiveFactory = ctx.primitives?.[primitive.name];
    if (typeof primitiveFactory === 'function') {
      const result = primitiveFactory(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    entranceTimeline.kill();

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.map = null;
      material.dispose?.();
    }

    loadedTexture?.dispose?.();
    root.clear();
  };

  return root;
}
